const number = formatNumber;
const gib = (n:number|undefined|null) => n == null ? '—' : number(n / 2**30, n < 2**30 ? 2 : 1);
const short = (n:number) => n>=1024 ? `${n/1024}K` : `${n}`;
const normalizeSettings = (value:Settings & {thinking?:boolean}):Settings => {
  const {thinking,...settings}=value;
  return {...settings,ngram_ram:settings.ngram_ram??true,gguf_offload:settings.gguf_offload??'layers',reasoning_effort:settings.reasoning_effort??(thinking===false?'off':'default')};
};
const OUTPUTS=[32768,16384,8192,4096,2048,1024,512,256];
/** Starting settings for a model: vision on when present, Auto answer length (the
 * rest of the context window, like llama.cpp's own UI), 4K prompt
 * chunks, MTP at 2 draft tokens when available, Q8 cache, and a CPU share
 * estimated from this computer's GPU and RAM. */
const defaults = (model:Model, hw?:Hardware|null, ggufMtp=true):Settings => {
  const qwen=model.name.startsWith('Qwen3.8-Flash-Next-EXL3');
  const deep=model.name.startsWith('DeepSeek')&&model.format==='EXL3';
  const gguf=model.format==='GGUF';
  const context=Math.floor(Math.min(gguf?131072:262144,model.context)/256)*256;
  const fit=hw?modelFit(model,hw):null, estimated=fit&&fit.level!=='unknown'?fit.cpuShare:null;
  const mtp=model.mtp&&(model.engines[0]==='exl3'||(gguf&&ggufMtp));
  return {model_id:model.id,engine:'auto',context,kv:'Q8',vision:model.vision,ngram_ram:true,
    prediction:mtp?'mtp':'off',draft_tokens:Math.min(2,model.draft_limit||2),max_output:0,
    cpu_percent:gguf?(estimated??(model.bytes>26*2**30?10:0)):qwen?60:deep?80:model.experts&&estimated!=null?estimated:80,
    gguf_offload:gguf&&model.experts>0?'experts':'layers',cpu_threads:8,chunk_size:4096,temperature:gguf?1:0.7,reasoning_effort:'default'};
};

async function api(path:string, body?:unknown, method?:string) {
  const response = await fetch(path,{method:method||(body === undefined?'GET':'POST'),headers:body===undefined&&!method?{}:{'Content-Type':'application/json','X-Inflect-Local':'1'},body:body===undefined?undefined:JSON.stringify(body)});
  if(!response.ok){let data;try{data=await response.json()}catch{data={detail:response.statusText}}
    if(response.status===404&&data.detail==='Not Found')throw new Error('The running Inflect server is older than this page and does not know this feature yet. Restart Inflect to finish updating.');
    throw new Error(typeof data.detail==='string'?data.detail:Array.isArray(data.detail)?data.detail.map((item:any)=>item.msg).join(' '):JSON.stringify(data.detail))}
  return response.json();
}

async function writeClipboard(text:string) {
  try {
    if(navigator.clipboard){await navigator.clipboard.writeText(text);return}
  } catch {}
  const area=document.createElement('textarea');
  area.value=text;area.readOnly=true;area.style.position='fixed';area.style.opacity='0';area.style.pointerEvents='none';
  document.body.appendChild(area);area.select();const copied=document.execCommand('copy');area.remove();
  if(!copied)throw new Error('Clipboard unavailable');
}

function Toggle({checked,onChange,disabled=false,label}:{checked:boolean;onChange:(v:boolean)=>void;disabled?:boolean;label:string}) {
  return <button type="button" role="switch" aria-checked={checked} aria-label={label} disabled={disabled} className={`toggle ${checked?'on':''}`} onClick={()=>onChange(!checked)}><span/></button>;
}

function Metric({icon:Icon,label,value,unit,detail,percent,history}:{icon:any;label:string;value:string;unit?:string;detail:string;percent?:number|null;history?:number[]}) {
  return <div className="metric"><div className="metric-label"><Icon size={15}/>{label}{history&&<svg className="sparkline" viewBox="0 0 78 20" aria-hidden="true"><polyline points={history.map((v,i)=>`${i*78/Math.max(history.length-1,1)},${19-Math.min(v,100)*.18}`).join(' ')} fill="none" stroke="currentColor" strokeWidth="1.5"/></svg>}</div><div className="metric-value">{value}<span>{unit}</span></div><div className="metric-detail">{detail}</div>{percent!=null&&<div className="meter"><i style={{width:`${Math.min(percent,100)}%`}}/></div>}</div>;
}

function Vital({icon:Icon,label,value,unit,tip,percent,className=''}:{icon?:any;label:string;value:string;unit?:string;tip:string;percent?:number|null;className?:string}) {
  return <div className={`vital ${className} ${percent!=null&&percent>=92?'high':''}`} title={tip} tabIndex={0}>{Icon&&<Icon size={14}/>}<span className="vital-label">{label}</span><span className="vital-value">{value}{unit&&<small>{unit}</small>}</span>{percent!=null&&<span className="vital-bar" aria-hidden="true"><i style={{width:`${Math.min(Math.max(percent,0),100)}%`}}/></span>}</div>;
}
const readFlag=(key:string)=>{try{return localStorage.getItem(key)==='1'}catch{return false}};

