  const ready=!loadTarget&&session?.state==='ready', loading=!!loadTarget||session?.state==='loading'||session?.state==='stopping', active=ready&&session?.model?.id===selected?.id;
  const liveSettings:Settings|null=loadTarget?pendingSettings:['loading','ready'].includes(session?.state)?session?.settings:null;
  const live:LiveSetup|null=liveSettings?{settings:liveSettings,state:loadTarget||session?.state==='loading'?'loading':'loaded',profileId:profiles.find(p=>sameSettings(p.settings,liveSettings))?.id||null}:null;
