  const applyInventory=(data:any)=>{setModels(data.models);setInventoryErrors(data.errors);setModelRoot(data.root);setLocations(data.locations||[]);libraryRevision.current=data.revision??libraryRevision.current;setSelected(old=>old?data.models.find((m:Model)=>m.id===old.id)||old:old)};
